argv:
set -eu
pr=$1; github=$2; expected_head=$3; expected_base=$4; expected_ref=$5; ticket=$6; repo=$7; base=$8; root=$9
refresh() {
  actual_head=${actual_head:-$expected_head}; actual_base=${actual_base:-$expected_base}
  REPO=$repo PR=$pr HEAD=$actual_head BASESHA=$actual_base ROOT=$root bun -e 'const e={schemaVersion:"factory.event/v1",eventId:`merge-refresh:${process.env.REPO}:${process.env.PR}:${process.env.HEAD}:${process.env.BASESHA}`,type:"factory.merge.requested",source:"chain",subject:process.env.REPO,occurredAt:new Date().toISOString(),correlationId:`merge-refresh:${process.env.REPO}:${process.env.PR}`,causationId:null,payload:{repo:process.env.REPO}}; console.log(JSON.stringify(e))' | bun "$root/event-runtime/cli.mjs" inject - >/dev/null || true
}
view=$(gh pr view "$pr" --repo "$github" --json state,isDraft,mergeable,headRefOid,headRefName,baseRefName,labels)
actual_head=$(printf '%s' "$view" | jq -r .headRefOid)
actual_base=$(gh api "repos/$github/git/ref/heads/$base" --jq .object.sha)
if [ "$actual_head" != "$expected_head" ] || [ "$actual_base" != "$expected_base" ]; then refresh; echo "stale reviewed SHA; fresh scan emitted" >&2; exit 0; fi
[ "$(printf '%s' "$view" | jq -r .state)" = OPEN ] || { echo "PR is not open" >&2; exit 1; }
[ "$(printf '%s' "$view" | jq -r .isDraft)" = false ] || { echo "PR is draft" >&2; exit 1; }
[ "$(printf '%s' "$view" | jq -r .mergeable)" = MERGEABLE ] || { refresh; echo "PR is not definitely mergeable" >&2; exit 0; }
[ "$(printf '%s' "$view" | jq -r .headRefName)" = "$expected_ref" ] || { refresh; echo "head branch moved" >&2; exit 0; }
[ "$(printf '%s' "$view" | jq -r .baseRefName)" = "$base" ] || { echo "base branch changed" >&2; exit 1; }
[ "$base" = develop ] || { echo "only develop is auto-mergeable" >&2; exit 1; }
! printf '%s' "$view" | jq -e '[.labels[].name|ascii_downcase] | any(. == "escalated" or . == "ai:escalated")' >/dev/null || { echo "escalation hold present" >&2; exit 1; }
! factory linear get "$ticket" | rg -qi 'ai:escalated|type:security|state[[:space:]]+Blocked' || { echo "Linear escalation/block hold present" >&2; exit 1; }
checks=$(gh pr checks "$pr" --repo "$github" --required --json bucket)
printf '%s' "$checks" | jq -e 'length > 0 and all(.[]; .bucket == "pass" or .bucket == "skipping")' >/dev/null || { refresh; echo "required CI missing, pending, or red" >&2; exit 0; }
gh pr merge "$pr" --repo "$github" --squash --match-head-commit "$expected_head"
landed=$(gh pr view "$pr" --repo "$github" --json state,mergeCommit --jq 'select(.state == "MERGED") | .mergeCommit.oid')
[ -n "$landed" ] || { echo "merge outcome uncertain" >&2; exit 1; }
REPO=$repo GITHUB=$github PR=$pr TICKET=$ticket HEAD=$expected_head HEADREF=$expected_ref BASE=$base MERGE=$landed ROOT=$root bun -e 'const p=process.env; const id=`merge-landed:${p.GITHUB}:${p.PR}:${p.MERGE}`; console.log(JSON.stringify({schemaVersion:"factory.event/v1",eventId:id,type:"factory.merge-landed",source:"chain",subject:p.REPO,occurredAt:new Date().toISOString(),correlationId:id,causationId:null,payload:{repo:p.REPO,github:p.GITHUB,base:p.BASE,pr:Number(p.PR),ticket:p.TICKET,headSha:p.HEAD,headRef:p.HEADREF,mergeCommitSha:p.MERGE}}))' | bun "$root/event-runtime/cli.mjs" inject -
